// Fixed code: Secure file download endpoint with path validation to prevent traversal
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Path;
import java.nio.file.Paths;

@WebServlet("/download")
public class SecureFileDownloadServlet extends HttpServlet {
    private static final String PUBLIC_ASSET_DIR = "/var/webapp/public_assets/";
    // Precompute canonical, absolute path of the allowed directory once on initialization
    private Path allowedBasePath;

    @Override
    public void init() throws ServletException {
        try {
            // toRealPath() resolves symlinks and normalizes the path to its canonical form
            allowedBasePath = Paths.get(PUBLIC_ASSET_DIR).toRealPath();
        } catch (IOException e) {
            throw new ServletException("Failed to initialize public asset directory", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String requestedFile = request.getParameter("filename");

        // Early rejection of invalid input (null or null-byte injection attempts)
        if (requestedFile == null || requestedFile.contains("\0")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid filename");
            return;
        }

        // Resolve the requested file against the allowed base and normalize path sequences
        Path resolvedPath = allowedBasePath.resolve(requestedFile).normalize();

        // Critical security check: Ensure the resolved path is strictly within the allowed directory
        if (!resolvedPath.startsWith(allowedBasePath)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to this resource is denied");
            return;
        }

        // Serve the file only after all validation checks pass
        File targetFile = resolvedPath.toFile();
        if (targetFile.exists() && targetFile.isFile()) {
            response.setContentType("application/octet-stream");
            try (InputStream fileIn = new FileInputStream(targetFile);
                 OutputStream responseOut = response.getOutputStream()) {
                fileIn.transferTo(responseOut);
            }
        } else {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
        }
    }
}
